/* ================= preflight ================= */
function polyArea(ps) { let a = 0; for (const p of ps) { let s2 = 0; for (let i = 0, j = p.length - 1; i < p.length; j = i++) s2 += (p[j][0] + p[i][0]) * (p[j][1] - p[i][1]); a += s2 / 2; } return Math.abs(a); }
function textHeights(o) {
  if (o.t === 'text') return [[`Text “${(o.s || '').slice(0, 18)}”`, o.h]];
  if (o.t === 'mk' && (o.st === 'arabic' || o.st === 'roman')) return [['Index numerals', o.L]];
  if (o.t === 'ring' && o.num !== 'none') return [[`${KN[o.k]} numerals`, o.nh]];
  return [];
}
function smallest() {
  let line = Infinity, text = Infinity, hair = false;
  for (const o of doc.objs) { if (o.hid) continue;
    if (o.t === 'ring') { if (o.tk !== 'none') line = Math.min(line, o.mw, o.nw); if (o.bo || o.bi) line = Math.min(line, o.bw2); }
    if (o.t === 'mk' && !['arabic', 'roman'].includes(o.st)) line = Math.min(line, o.W);
    for (const [, hh] of textHeights(o)) text = Math.min(text, hh);
    const open = o.t === 'line' || (o.t === 'spl' && !o.closed);
    if (open || o.fill === false) { if (o.sw > 0) line = Math.min(line, o.sw); else hair = true; }
  }
  return {line, text, hair};
}
let pfThin = [];
function preflight(v) {
  const t = T(), out = [], minLine = v ? v.minLine || 0 : 0, minText = v ? v.minText || 0 : 0;
  const edge = OFF([dialPoly(t)], 0.005), keep = t.panel ? OFF([dialPoly(t)], 0.05 - doc.safe) : [circ(0, 0, t.R - doc.safe + 0.05)];
  const noGo = t.panel ? [] : U([...(t.hole ? [circ(0, 0, t.hole / 2)] : []), ...tplWins(t), ...(t.subs ? Object.values(t.subs).map(sb => circ(sb.x, -sb.y, t.sh / 2)) : [])]);
  pfThin = [];
  if (!doc.objs.some(o => !o.hid)) out.push({sev:'err', msg:'This design is empty.'});
  for (const o of doc.objs) {
    if (o.hid) continue; const g = geomOf(o);
    if (minText) for (const [lab, hh] of textHeights(o)) if (hh < minText - 1e-9) out.push({o, sev:'warn', msg:`${lab} is ${fmtL(hh)} ${UL()} tall. ${v.name} minimum: ${fmtL(minText)} ${UL()}${v.assumed ? ' (assumed, confirm with the test card)' : ''}.`});
    if (!g.F.length) continue;
    if (minLine) { const e = minLine * 0.15, th = OFF(OFF(DIFF(g.F, OFF(OFF(g.F, -minLine / 2), minLine / 2)), -e), e); if (polyArea(th) > minLine * minLine * 0.75) { pfThin.push(...th); out.push({o, sev:'warn', msg:`Has strokes thinner than ${fmtL(minLine)} ${UL()} (shown in red).`}); } }
    if (noGo.length && polyArea(INTER(g.F, noGo)) > 1e-3) out.push({o, sev:'err', msg:'Covers a window, the center hole or a hand hole.'});
    if (polyArea(DIFF(g.F, edge)) > 1e-3) out.push({o, sev:'err', msg:t.panel ? 'Runs past the panel edge.' : 'Runs past the dial edge.'});
    else if (polyArea(DIFF(g.F, keep)) > 1e-3) out.push({o, sev:'warn', msg:t.panel ? 'Sits inside the edge margin.' : 'Sits under the chapter-ring margin and may be hidden.'});
  }
  scheduleRender();
  return out;
}
